    SECTION code,code
    ; Copy the 42-byte helper at source $28 to low RAM $300 before moving the overlapping image. PC-relative LEAs recover the load base; custom interrupt and DMA enables are cleared.
bootstrap_to_fixed_execution_base:
    ORG $10000
abs_0_00010000:
	move.w #INTF_CLRALL,_custom+intena.l
	move.w #DMAF_CLRALL,_custom+dmacon.l
	lea.l fixed_base_image_copy_stub(pc),a0
	lea.l abs_0_00010000(pc),a1
	lea.l runtime_code_00000300.w,a2
	moveq.l #41,d0
abs_0_0001001E:
	move.b (a0)+,(a2)+
	dbf.w d0,abs_0_0001001E
	jmp runtime_code_00000300.w
    ; At $300, copy $55370 bytes from A1 to $10000, then jump to $1046A. Use forward copy for source >= destination, backward otherwise. The remaining file tail is not copied here.
fixed_base_image_copy_stub:
	lea.l abs_0_00010000.l,a2
	lea.l initialize_runtime_workspace.l,a3
	move.l #$55370,d0
	cmpa.l a2,a1
	bcs.b abs_0_00010046
copy_image_forward_bytes:
	move.b (a1)+,(a2)+
	subq.l #1,d0
	bne.b copy_image_forward_bytes
	jmp (a3)
abs_0_00010046:
	adda.l d0,a1
	adda.l d0,a2
copy_image_backward_bytes:
	move.b -(a1),-(a2)
	subq.l #1,d0
	bne.b copy_image_backward_bytes
	jmp (a3)
	dcb.b $400,$00
runtime_supervisor_stack_top:
	dc.b $00,$00,$00,$10
    ; Warm restart waits for blitter busy to clear before setup/title CPU reuse of shared scratch. Render helpers may return with the final scratch read active; this wait closes that transition.
wait_for_blitter_then_restart_runtime:
	lea.l _custom+dmaconr.l,a5
    ; A5 hardware ref: dmaconr at _custom+$0002; operand kept as (a5)
wait_for_restart_blitter_idle:
	move.w (a5),d0
	btst #DMAB_BLTDONE,d0
	bne.b wait_for_restart_blitter_idle
	move #$2700,sr
	bra.b setup_runtime_hardware_and_display
    ; Clear $36C bytes at fixed workspace $39FC, then install TRAP0 to enter supervisor setup. This workspace is separate from the copied program image.
initialize_runtime_workspace:
	lea.l APP_STATE_BASE.l,a0
	move.w #APP_STARTUP_CLEAR_LAST_BYTE,d0
clear_runtime_workspace_bytes:
	clr.b (a0)+
	dbf.w d0,clear_runtime_workspace_bytes
	lea.l runtime_supervisor_stack_top(pc),a7
	lea.l supervisor_runtime_entry(pc),a0
	move.l a0,m68k_vector_trap_0_instruction_vector.w
	trap #0
    ; Set SR=$2700 and bind A6=$39FC. This TRAP0 handler falls into setup without RTE; the later A7 reset discards the trap frame.
supervisor_runtime_entry:
	move #$2700,sr
	lea.l APP_STATE_BASE.l,a6
	jsr initialize_world_tilemap_state.l
setup_runtime_hardware_and_display:
	lea.l _custom.l,a5
	lea.l noop_runtime_callback(pc),a0
	move.w #$7FFF,d0
	move.w d0,dmacon(a5)
	move.w d0,intena(a5)
	move.w d0,intreq(a5)
	move.l a0,app_vertical_blank_callback(a6)
	move.l a0,$0190(a6)
    ; Reset the active stack to source $452 (runtime $10452 here) after supervisor entry. The temporary TRAP0 frame is not returned through.
	lea.l runtime_supervisor_stack_top(pc),a7
	moveq.l #-1,d0
	move.w d0,bltafwm(a5)
	move.w d0,bltalwm(a5)
	clr.w bltcon1(a5)
	move.w #DMAF_SETCLR|DMAF_BLITHOG|DMAF_MASTER|DMAF_BLITTER,dmacon(a5)
	bsr.w prime_blitter_completion_request
	jsr initialize_world_state.l
	lea.l handle_level_3_interrupts(pc),a0
	move.l a0,m68k_vector_level_3_interrupt_autovector.w
    ; Configure four bitplanes with modulo 120. The frame callback sets plane starts 40 bytes apart, forming an interleaved plane layout.
	moveq.l #120,d0
	move.w d0,bpl1mod(a5)
	move.w d0,bpl2mod(a5)
	move.w #(4<<PLNCNTSHFT)|COLORON,bplcon0(a5)	; display 4 bitplanes lores color
	move.w #$2C81,diwstrt(a5)	; display window start v=$2C h=$81
	move.w #$F4C1,diwstop(a5)	; display window stop v=$F4 h=$C1
	move.w #$38,ddfstrt(a5)	; display fetch start $38
	move.w #$D0,ddfstop(a5)	; display fetch stop $D0
	move.w #DMAF_SETCLR|DMAF_BLITHOG|DMAF_MASTER|DMAF_COPPER|DMAF_BLITTER,dmacon(a5)
	move #$2000,sr
    ; Enable master, vertical-blank and Copper interrupts here; BLIT is not enabled by this write. The level-3 handler samples raw request bits.
	move.w #INTF_SETCLR|INTF_INTEN|INTF_VERTB|INTF_COPER,intena(a5)
	bsr.w run_title_starfield_until_fire
	move.w #DMAF_RASTER,dmacon(a5)
	lea.l handle_vertical_blank_frame_update(pc),a0
	move.l a0,app_vertical_blank_callback(a6)
	lea.l apply_gameplay_overlay_palette_and_arm_lower_split(pc),a0
	move.l a0,app_copper_interrupt_callback(a6)
	lea.l gameplay_split_display_copper_list(pc),a0
	move.l a0,cop1lc(a5)	; copper_list pointer
	lea.l initial_gameplay_palette_rgb12(pc),a0
	move.l a0,app_current_palette(a6)
	bsr.w start_seeded_zero_copy_blit
    ; Render both fixed buffer banks ($78000, then $70000). Initial front/display is $78000 and back is $70000; these chip-visible placements are not arbitrary-base relocation.
	move.l #FRAMEBUFFER_BANK1_BASE,app_display_bitplane_base(a6)
	move.l #FRAMEBUFFER_BANK1_BASE,app_back_bitplane_base(a6)
	bsr.w render_tilemap_view_to_back_buffer
	move.l #FRAMEBUFFER_BANK0_BASE,app_back_bitplane_base(a6)
	bsr.w render_tilemap_view_to_back_buffer
	move.l #FRAMEBUFFER_BANK1_BASE,app_front_bitplane_base(a6)
	bsr.w abs_0_0001079E
	jsr initialize_player_and_fixed_animation_nodes.l
	bsr.w run_eligible_world_object_scripts
	bsr.w repeat_inherited_object_xy_copy_for_world_table
	bsr.w advance_active_descriptor_animation_chains
	bsr.w update_nearby_object_detection
	bsr.w snapshot_entity_draw_state
	bsr.w wait_for_next_frame_counter
	lea.l _custom.l,a5
	move.w #DMAF_SETCLR|DMAF_RASTER|DMAF_SPRITE,dmacon(a5)
	move.b #GAMEPLAY_FADE_SETUP_STEPS,app_palette_transition_steps_remaining(a6)
	bra.b wait_for_completed_frame
    ; Exchange front/back pointers, select the new front for display, then clear completion bit 5 before waiting for the next completed frame callback.
swap_front_back_display_buffers:
	move.l app_front_bitplane_base(a6),d1
	move.l app_back_bitplane_base(a6),d0
	move.l d0,app_front_bitplane_base(a6)
	move.l d1,app_back_bitplane_base(a6)
	move.l d0,app_display_bitplane_base(a6)
	bclr.b #APP_STATUS_FRAME_COMPLETE_BIT,app_status_flags(a6)
    ; Wait for frame-callback completion bit 5. Initial entry skips the buffer exchange/clear; later loop iterations clear the latch before waiting.
wait_for_completed_frame:
	btst.b #APP_STATUS_FRAME_COMPLETE_BIT,app_status_flags(a6)
	beq.b wait_for_completed_frame
	bsr.w service_nearby_trade_or_combat
	bsr.w update_inventory_panel_availability
	bsr.w update_camera_scroll
	bsr.w handle_inventory_panel_input
	bsr.w snapshot_entity_draw_state
	bsr.w advance_active_descriptor_animation_chains
	bsr.w run_eligible_world_object_scripts
	bsr.w update_nearby_object_detection
	jsr process_security_checkpoint_response.l
	jsr service_selected_ranged_weapon_fire.l
	bsr.w update_world_object_interactions
	jsr process_terminal_item_deposit.l
	bsr.w service_keyboard_pause_gate
	lea.l _custom.l,a5
	jsr poll_joystick1_directions_and_fire.l
	jsr service_status_message_duration.l
	bsr.w service_gameplay_palette_transition
	bsr.w update_earth_orbit_countdown_display
	jsr advance_pseudorandom_state.l
	jsr update_player_proximity_audio.l
	btst.b #GAME_EVENT_SELF_DESTRUCT_EXPIRED_BIT,app_game_event_flags(a6)
	bne.b abs_0_00010676
	btst.b #GAME_EVENT_ESCAPE_TRIGGERED_BIT,app_game_event_flags(a6)
	bne.b abs_0_00010676
	tst.b app_self_destruct_state(a6)
	bpl.b abs_0_0001066C
	move.w app_self_destruct_service_ticks_remaining(a6),d0
	subq.w #1,d0
	bmi.w handle_self_destruct_countdown_expiry
	move.w d0,app_self_destruct_service_ticks_remaining(a6)
	andi.b #127,d0
	bne.b abs_0_0001066C
	lea.l self_destruct_evacuation_warning.l,a0
	bsr.w enqueue_scrolling_message
	bsr.w enqueue_blank_scrolling_message
	move.w #$310,d0
	jsr start_feedback_audio_sequence.l
abs_0_0001066C:
	btst.b #1,player_world_object_world_object_flags.l
	beq.b check_main_keyboard_shortcuts
abs_0_00010676:
	btst.b #CONTEXT_STATUS_MESSAGE_ACTIVE_BIT,app_context_flags(a6)
	bne.b check_main_keyboard_shortcuts
	subq.b #1,app_game_exit_service_ticks_remaining(a6)
	bne.b check_main_keyboard_shortcuts
	bra.w wait_for_blitter_then_restart_runtime
check_main_keyboard_shortcuts:
	btst.b #APP_STATUS_CAMERA_SCROLL_ACTIVE_BIT,app_status_flags(a6)
	bne.b continue_main_frame_exchange
	lea.l KEYBOARD_STATE_BASE.l,a0
    ; KNOWN: type A0=Target code-entry register seed:keyboard_state_table
	tst.b keyboard_state_table_warm_restart_f7_held_ff(a0)
	beq.b check_camera_profile_0_key
	jmp wait_for_blitter_then_restart_runtime.l
check_camera_profile_0_key:
	tst.b keyboard_state_table_scroll_profile_0_held_ff(a0)
	beq.b check_camera_profile_1_key
	tst.w app_camera_scroll_profile_index(a6)
	beq.b continue_main_frame_exchange
	clr.w app_camera_scroll_profile_index(a6)
