update_star_motion:
	move.w title_star_record_origin_x.w(a2),d0
	asl.w #4,d0
	move.b title_star_record_lifetime(a2),d1
	ext.w d1
	ext.l d0
	divs.w d1,d0
	move.w d0,title_star_record_projected_x(a2)
	move.w title_star_record_origin_y(a2),d0
	asl.w #4,d0
	ext.l d0
	divs.w d1,d0
	move.w d0,title_star_record_projected_y(a2)
	subq.b #1,d1
	move.b d1,title_star_record_lifetime(a2)
	cmp.b #TITLE_STAR_LIFETIME_RESEED_AT,d1
	rts
reset_star_motion:
	bsr.w advance_pseudorandom_state
	andi.w #255,d0
	cmp.b #$A0,d0
	bcs.b abs_0_00010BE6
	lsr.b #1,d0
abs_0_00010BE6:
	tst.w d1
	bpl.b abs_0_00010BEC
	neg.w d0
abs_0_00010BEC:
	move.w d0,title_star_record_origin_x.w(a2)
	asl.w #4,d0
	asr.w #6,d0
	move.w d0,title_star_record_projected_x(a2)
	swap.w d1
	move.l d1,d0
	andi.w #127,d0
	cmp.b #$64,d0
	bcs.b abs_0_00010C08
	lsr.b #1,d0
abs_0_00010C08:
	tst.w d1
	bpl.b abs_0_00010C0E
	neg.w d0
abs_0_00010C0E:
	move.w d0,title_star_record_origin_y(a2)
	asl.w #4,d0
	asr.w #6,d0
	move.w d0,title_star_record_projected_y(a2)
	move.b #TITLE_STAR_LIFETIME_RESET,title_star_record_lifetime(a2)
	rts
initialize_star_motion_with_random_lifetime:
	bsr.b reset_star_motion
    ; KNOWN: type A2=Target code-entry register seed:title_star_record
abs_0_00010C24:
	bsr.w advance_pseudorandom_state
	andi.b #TITLE_STAR_LIFETIME_MASK,d1
	addq.b #1,d1
	cmp.b #TITLE_STAR_MIN_VISIBLE_LIFETIME,d1
	bcs.b abs_0_00010C24
	move.b d1,title_star_record_lifetime(a2)
	move.w title_star_record_origin_x.w(a2),d0
	asl.w #4,d0
	ext.w d1
	ext.l d0
	divs.w d1,d0
	move.w d0,title_star_record_projected_x(a2)
	move.w title_star_record_origin_y(a2),d0
	asl.w #4,d0
	ext.l d0
	divs.w d1,d0
	move.w d0,title_star_record_projected_y(a2)
	rts
clear_star_pixel:
	moveq.l #0,d2
	bra.b dispatch_star_pixel_color
    ; Lifetimes 17..64 select colors 1..7: 1+((lifetime-16)>>3). Clear uses color 0. AND #7 later selects the pixel bit; it does not clamp the dispatch index.
render_star_pixel_by_lifetime:
	moveq.l #0,d2
	move.b title_star_record_lifetime(a2),d2
	subi.b #TITLE_STAR_LIFETIME_RESEED_AT,d2
	lsr.b #TITLE_STAR_COLOR_LIFETIME_SHIFT,d2
	addq.b #1,d2
dispatch_star_pixel_color:
	move.w title_star_record_projected_x(a2),d0
	move.w title_star_record_projected_y(a2),d1
	addi.w #160,d0
	addi.w #100,d1
	move.w d0,d3
	lsr.w #3,d3
	add.w d1,d1
	add.w $0(a6,d1.w),d3
	move.b d0,d1
	not.b d1
	andi.w #7,d1
	moveq.l #0,d0
	move.w d3,d0
	movea.l app_front_bitplane_base(a6),a0
