    ; A0 bitset, D0.W index. Tests MSB-first; Z is clear when set. Preserves D0/D1; caller supplies a valid index.
test_msb_first_bitset_bit:
	movem.l d0-d1,-(a7)
	move.w d0,d1
	lsr.w #3,d1
	eori.b #7,d0
	btst.b d0,$0(a0,d1.w)
	movem.l (a7)+,d0-d1
	rts
toggle_bitmap_pixel_bit:
	movem.l d0-d1,-(a7)
	move.w d0,d1
