	movem.l (a7)+,a0-a3/a5
	rts
    ; X WORD >>3 is aligned to an even byte. Row lookup uses signed WORD(2*Y), without a bounds check. Offset addition wraps as WORD; ADDA.W sign-extends it. D0-D2 are preserved.
get_back_buffer_word_address:
	movem.l d0-d2,-(a7)
	lsr.w #BITMAP_PIXELS_PER_BYTE_SHIFT,d0
	bclr #0,d0
	add.w d1,d1
	add.w APP_RASTER_ROW_OFFSETS_OFFSET(a6,d1.w),d0
	movea.l app_back_bitplane_base(a6),a1
	adda.w d0,a1
	movem.l (a7)+,d0-d2
	rts
    ; D2 low WORD returns the aligned offset; D0/D1 and D2 high WORD survive. Signed WORD row indexing and wrapped offset remain unchecked. No static callers are known.
calculate_tilemap_buffer_offset:
	move.l d1,-(a7)
	move.w d0,d2
	lsr.w #BITMAP_PIXELS_PER_BYTE_SHIFT,d2
	andi.b #BITMAP_WORD_ALIGNMENT_MASK,d2
	add.w d1,d1
	add.w APP_RASTER_ROW_OFFSETS_OFFSET(a6,d1.w),d2
	move.l (a7)+,d1
	rts
copy_world_object_field_30_to_indirect_slot_4:
	movea.l $002C(a5),a0
	move.l $0030(a5),$0004(a0)
	rts
copy_world_object_field_36_to_indirect_slot_4:
	movea.l $002C(a5),a0
	move.l $0036(a5),$0004(a0)
	rts
copy_world_object_field_30_to_field_36:
	move.l $0030(a5),$0036(a5)
	rts
    ; Restore background tiles in the saved entity/attachment rectangle, rounded to 16-pixel tile bounds and clipped to the view.
restore_entity_background:
	move.l world_position_descriptor_prefix_position_state_ptr.w(a0),d0
find_first_previous_geometry:
	beq.b restore_entity_background_return
	movea.l d0,a4
	tst.l world_position_state_record_previous_geometry_ptr(a4)
	bne.b begin_previous_geometry_union
	move.l world_position_state_record_attachment_state_ptr(a4),d0
	bra.b find_first_previous_geometry
begin_previous_geometry_union:
	move.w world_position_descriptor_prefix_previous_world_x(a0),d0
	move.w world_position_descriptor_prefix_previous_world_y(a0),d1
	bsr.b get_previous_rect_start
	bsr.b get_previous_rect_end
	move.l d4,d2
	move.l d5,d3
union_next_attachment_geometry:
	move.l world_position_state_record_attachment_state_ptr(a4),d6
	beq.w restore_clipped_tile_rectangle
	movea.l d6,a4
	bsr.b get_previous_rect_start
	cmp.w d2,d4
	bcc.b union_previous_rectangle_min_y
	move.w d4,d2
union_previous_rectangle_min_y:
	cmp.w d3,d5
	bcc.b union_previous_rectangle_maxima
	move.w d5,d3
union_previous_rectangle_maxima:
	bsr.b get_previous_rect_end
	swap.w d2
	swap.w d4
	cmp.w d2,d4
	bls.b union_previous_rectangle_max_y
	move.w d4,d2
union_previous_rectangle_max_y:
	swap.w d2
	swap.w d4
	swap.w d3
	swap.w d5
	cmp.w d3,d5
	bls.b union_previous_rectangle_next_attachment
	move.w d5,d3
union_previous_rectangle_next_attachment:
	swap.w d3
	swap.w d5
	bra.b union_next_attachment_geometry
restore_entity_background_return:
	rts
get_previous_rect_start:
	movea.l world_position_state_record_previous_geometry_ptr(a4),a3
	move.w world_position_state_record_world_x_offset(a4),d4
	move.w world_position_state_record_world_y_offset(a4),d5
	add.w d0,d4
	add.w d1,d5
	add.w world_position_collision_bounds_world_y_origin_offset(a3),d5
	rts
    ; D4/D5 return packed end:start coordinate pairs for the rectangle union.
get_previous_rect_end:
	movea.l world_position_state_record_previous_geometry_ptr(a4),a3
	swap.w d4
	swap.w d5
	move.w world_position_state_record_world_x_offset(a4),d4
	move.w world_position_state_record_world_y_offset(a4),d5
	add.w d0,d4
	add.w d1,d5
	add.w world_position_collision_bounds_world_x_origin_offset(a3),d4
	add.w world_position_collision_bounds_world_y_origin_offset(a3),d5
	add.w world_position_collision_bounds_world_x_extent(a3),d4
	add.w world_position_collision_bounds_world_y_extent(a3),d5
	swap.w d4
	swap.w d5
	rts
    ; Round union outward to inclusive 16-pixel tile bounds; clip, shorten rows/columns and advance the source grid. REJECT skips the copy, including the all-four-sides flag combination.
restore_clipped_tile_rectangle:
	move.l a0,-(a7)
	move.l d2,d5
	move.l d3,d6
	moveq.l #-16,d0
	and.w d0,d2
	and.w d0,d3
	swap.w d2
	swap.w d3
	moveq.l #15,d0
	or.w d0,d2
	or.w d0,d3
	move.w d3,d6
	move.w d2,d5
	swap.w d2
	swap.w d3
	bsr.w clip_tile_region_to_view
	cmp.b #VIEW_CLIP_REJECT,d4
	beq.w restore_tile_rectangle_return
	addq.w #1,d5
	addq.w #1,d6
	sub.w d2,d5
	sub.w d3,d6
	lsr.w #4,d5
	lsr.w #4,d6
	exg d0,d2
	exg d1,d3
	bsr.w get_tilemap_cell_pointer
	tst.b d4
	beq.w restore_visible_tile_rectangle
	btst #VIEW_CLIP_LEFT_BIT,d4
	beq.b restore_clip_right_tiles
	move.w d2,d7
	sub.w d0,d7
	add.w d7,d0
	lsr.w #4,d7
	sub.w d7,d5
	add.w d7,d7
	add.w d7,d7
	adda.w d7,a0
	bra.w restore_clip_vertical_tiles
restore_clip_right_tiles:
	btst #VIEW_CLIP_RIGHT_BIT,d4
	beq.b restore_clip_vertical_tiles
	swap.w d0
	move.w d0,d7
	swap.w d0
	swap.w d2
	addq.w #1,d7
	sub.w d2,d7
	lsr.w #4,d7
	sub.w d7,d5
	swap.w d2
restore_clip_vertical_tiles:
	btst #VIEW_CLIP_TOP_BIT,d4
	beq.b restore_clip_bottom_tiles
	move.w d3,d7
	sub.w d1,d7
	move.w d3,d1
	lsr.w #4,d7
	sub.w d7,d6
	mulu.w app_tilemap_width(a6),d7
	add.w d7,d7
	add.w d7,d7
	adda.w d7,a0
	bra.w restore_visible_tile_rectangle
restore_clip_bottom_tiles:
	btst #VIEW_CLIP_BOTTOM_BIT,d4
	beq.b restore_visible_tile_rectangle
	swap.w d1
	move.w d1,d7
	swap.w d1
	swap.w d3
	addq.w #1,d7
	sub.w d3,d7
	lsr.w #4,d7
	sub.w d7,d6
	swap.w d3
restore_visible_tile_rectangle:
	sub.w d3,d1
	sub.w d2,d0
	bsr.w get_back_buffer_word_address
	move.w d5,d0
	move.w d6,d1
	bsr.w blit_tile_pointer_rectangle_to_buffer
restore_tile_rectangle_return:
	movea.l (a7)+,a0
	rts
draw_entity_geometry_chain:
	movea.l world_position_descriptor_prefix_position_state_ptr.w(a0),a0
draw_next_geometry_attachment:
	bsr.b draw_entity_geometry
	move.l world_position_state_record_attachment_state_ptr(a0),d0
	beq.b draw_geometry_chain_return
	movea.l d0,a0
	bra.b draw_next_geometry_attachment
draw_geometry_chain_return:
	rts
    ; Draw current geometry at XY plus animation offsets. Original H<=48 bounds scratch to768B after nonwrapping clipping; fully clipped geometry sets bit0. DMA input bounds remain separate.
draw_entity_geometry:
	movem.l a0/a5,-(a7)
	tst.l world_position_state_record_current_geometry_ptr.w(a0)
	beq.w draw_geometry_return
	movea.l world_position_state_record_position_descriptor_ptr(a0),a1
	move.w world_position_state_record_world_x_offset(a0),d0
	move.w world_position_state_record_world_y_offset(a0),d1
	add.w world_position_descriptor_prefix_world_x(a1),d0
	add.w world_position_descriptor_prefix_world_y(a1),d1
	movea.l world_position_state_record_current_geometry_ptr.w(a0),a2
	add.w world_position_collision_bounds_world_y_origin_offset(a2),d1
	movea.l world_position_collision_bounds_bitplane_data_ptr.w(a2),a3
	movea.l world_position_collision_bounds_mask_data_ptr(a2),a4
	move.w d0,d2
	add.w world_position_collision_bounds_world_x_origin_offset(a2),d2
	add.w world_position_collision_bounds_world_x_extent(a2),d2
	swap.w d2
	move.w d0,d2
	move.w d1,d3
	add.w world_position_collision_bounds_world_y_extent(a2),d3
	swap.w d3
	move.w d1,d3
	bsr.w clip_tile_region_to_view
	cmp.b #VIEW_CLIP_REJECT,d4
	beq.w mark_geometry_outside_view
	bclr.b #WORLD_STATE_OUTSIDE_VIEW_BIT,world_position_state_record_interaction_flags(a0)
